	,OnScreen: function() {
		if(this.rect == null || this.handle == null) {
			return false;
		}
		var rw = this.rect.width;
		var rh = this.rect.height;
		var lx = this.loc.x;
		var ly = this.loc.y;
		var hx = this.handle.x;
		var hy = this.handle.y;
		var o0x = (-rw / 2 + hx) * this.xScale;
		var o0y = (-rh / 2 + hy) * this.yScale;
		var o1x = (rw / 2 + hx) * this.xScale;
		var o1y = (-rh / 2 + hy) * this.yScale;
		var o2x = (-rw / 2 + hx) * this.xScale;
		var o2y = (rh / 2 + hy) * this.yScale;
		var o3x = (rw / 2 + hx) * this.xScale;
		var o3y = (rh / 2 + hy) * this.yScale;
		var cr = 0;
		var sr = 0;
		if(this.rot != 0) {
			var cr = Math.cos(this.rot);
			var sr = Math.sin(this.rot);
			var tx = lx + o0x * cr - o0y * sr;
			var ty = ly + o0x * sr + o0y * cr;
			if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
				return true;
			}
			tx = lx + o1x * cr - o1y * sr;
			ty = ly + o1x * sr + o1y * cr;
			if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
				return true;
			}
			tx = lx + o2x * cr - o2y * sr;
			ty = ly + o2x * sr + o2y * cr;
			if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
				return true;
			}
			tx = lx + o3x * cr - o3y * sr;
			ty = ly + o3x * sr + o3y * cr;
			if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
				return true;
			}
		}
		var tx = Main.ZOOM * (lx + o0x);
		var ty = Main.ZOOM * (ly + o0y);
		if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
			return true;
		}
		tx = Main.ZOOM * (lx + o1x);
		ty = Main.ZOOM * (ly + o1y);
		if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
			return true;
		}
		tx = Main.ZOOM * (lx + o2x);
		ty = Main.ZOOM * (ly + o2y);
		if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
			return true;
		}
		tx = Main.ZOOM * (lx + o3x);
		ty = Main.ZOOM * (ly + o3y);
		if(tx >= 0 && tx < Main.SCREENWIDTH && ty >= 0 && ty < Main.SCREENHEIGHT) {
			return true;
		}
		if(this.rect.width * this.xScale > Main.SCREENWIDTH || this.rect.height * this.yScale > Main.SCREENHEIGHT) {
			return true;
		}
		return false;
	}
