	,HideSideBanners: function() {
		if(Main.crazyGames) {
			return;
		}
		Main.showSideAds = false;
		this.onStageResize();
		var aCS = Main.GetChildByType(characterselectscreen_CharacterSelectScreen);
		if(aCS != null) {
			aCS.Relocate();
			var h = aCS.holder;
			if(h != null) {
				var hRot = h.rot;
				var hXScale = h.xScale;
				var hYScale = h.yScale;
				var hHandleX = aCS.local_loc.x + h.handle.x;
				var hHandleY = aCS.local_loc.y + h.handle.y;
				var hx = h.loc.x;
				var hy = h.loc.y;
				var a = aCS.xScale * aCS.yScale;
				aCS.rot = hRot + (a > 0 ? 1 : a < 0 ? -1 : 0) * aCS.local_rot;
				if(hRot == 0) {
					aCS.loc.x = hx + hXScale * hHandleX;
					aCS.loc.y = hy + hYScale * hHandleY;
				} else {
					var x = hRot;
					while(x < -Math.PI) x += Math.PI * 2;
					while(x > Math.PI) x -= Math.PI * 2;
					var sin = 0;
					if(x < 0) {
						sin = 1.27323954 * x + .405284735 * x * x;
					} else {
						sin = 1.27323954 * x - 0.405284735 * x * x;
					}
					var gSin = sin;
					var x = hRot;
					while(x < -Math.PI) x += Math.PI * 2;
					while(x > Math.PI) x -= Math.PI * 2;
					x += 1.57079632;
					if(x > 3.14159265) {
						x -= 6.28318531;
					}
					var cos = 1;
					if(x < 0) {
						cos = 1.27323954 * x + 0.405284735 * x * x;
					} else {
						cos = 1.27323954 * x - 0.405284735 * x * x;
					}
					var gCos = cos;
					aCS.loc.x = hx + hXScale * hHandleX * gCos - hYScale * hHandleY * gSin;
					aCS.loc.y = hy + hXScale * hHandleX * gSin + hYScale * hHandleY * gCos;
				}
			}
		}
	}
