	,onTouchBegin: function(e) {
		if(e == null) {
			return;
		}
		var aX = e.localX / Main.ZOOM;
		var aY = e.localY / Main.ZOOM;
		var touchPoint = new openfl_geom_Point(aX,aY);
		Main.touches.h[e.touchPointID] = touchPoint;
		if(Main.mState == 0) {
			Main.mClicked = true;
		}
		Main.mState = 1;
		Main.mX = aX;
		Main.mY = aY;
	}
	,onTouchMove: function(e) {
		var aX = e.localX / Main.ZOOM;
		var aY = e.localY / Main.ZOOM;
		var touchPoint = Main.touches.h[e.touchPointID];
		if(touchPoint == null) {
			touchPoint = new openfl_geom_Point(aX,aY);
			Main.touches.h[e.touchPointID] = touchPoint;
		}
		touchPoint.x = aX;
		touchPoint.y = aY;
	}
	,onTouchEnd: function(e) {
		var touchPoint = Main.touches.h[e.touchPointID];
		if(touchPoint != null) {
			Main.touches.remove(e.touchPointID);
		}
		var aX = e.localX / Main.ZOOM;
		var aY = e.localY / Main.ZOOM;
		Main.mX = aX;
		Main.mY = aY;
		Main.mState = 0;
	}
