	,CycleLights: function(intensity) {
		if(intensity == null) {
			intensity = 1;
		}
		var baseAlp = .18;
		var dir = 1.0;
		var baseWait = 0;
		var _g = 0;
		while(_g < 20) {
			var i = _g++;
			var sc = Rnd.float(.5,1.5,true);
			var a = Misc.AddFlash(this.bknd2,Rnd.integer(0,2200,true),sc,sc,1);
			a.local_loc.x = Rnd.float(-this.bknd2.rect.width / 2,this.bknd2.rect.width / 2,true);
			a.local_loc.y = Rnd.float(-this.bknd2.rect.height / 2,this.bknd2.rect.height / 2,true);
		}
		var _g = 0;
		var _g1 = this.lights;
		while(_g < _g1.length) {
			var light = _g1[_g];
			++_g;
			light.movements = new haxe_ds_List();
			light.AddMovement(5,0,Math.PI / 4,1000,false,0);
			light.AddMovement(5,Math.PI / 4,0,1000,false,0);
			light.AddMovement(5,0,Math.PI / 4,1000,false,0);
			light.AddMovement(5,Math.PI / 4,0,1000,false,0);
			var antiDir = 1.0 - dir;
			var _g2 = 0;
			var _g3 = light.children;
			while(_g2 < _g3.length) {
				var o = _g3[_g2];
				++_g2;
				o.movements = new haxe_ds_List();
				var _g4 = 0;
				while(_g4 < 40) {
					var i = _g4++;
					o.AddMovement(4,baseAlp,baseAlp * intensity,100);
					var period = .5;
					if(period == null) {
						period = 0;
					}
					var f = o.fromPool ? GameObject.filterPool.pop() : null;
					if(f == null) {
						f = new Filter();
					}
					f.type = 1;
					f.amplitude = -baseAlp * intensity;
					f.period = period;
					f.offset = 0;
					f.splineArr = null;
					f.curves = null;
					o.lastMovement.movementFilters.push(f);
				}
				o.AddMovement(4,baseAlp,baseAlp,100);
			}
			dir = antiDir;
			baseWait += 100;
		}
	}
