	,alternator: null
	,PointScored: function(b,doPanel) {
		if(doPanel == null) {
			doPanel = true;
		}
		var a = ++this.alternator % 3;
		if(Main.player.practiceMode) {
			Misc.PlaySound(CROWD_$ROAR_$WAV.Get());
			if(!b.dunked && b.rimCount <= 1) {
				Misc.PlaySound(SWISH_$WAV.Get());
			}
			var guy = b.shotBy;
			if(guy == null) {
				return;
			}
			guy.shotStreak++;
			if(((guy) instanceof HumanGuy)) {
				guy.fgMade++;
				if(MainGame.shotPoints == 3) {
					guy.threePointMade++;
					MainGame.thisMG.panel.CalcPercent();
				}
			}
			return;
		}
		if(this.mode == GameModes.MODE_POINT_SCORED) {
			return;
		}
		this.mode = GameModes.MODE_POINT_SCORED;
		var a = b.local_loc.x;
		MainGame.lastSideScored = a > 0 ? 1 : a < 0 ? -1 : 0;
		b.isShot = false;
		if(doPanel) {
			this.panel.PointScored(b);
		}
		b.shotBy = null;
		this.CycleLights(2);
		var _g = 0;
		var _g1 = this.children;
		while(_g < _g1.length) {
			var o = _g1[_g];
			++_g;
			if(((o) instanceof Guy)) {
				var guy = o;
				if(guy.side == Sides.SIDE_RIGHT && b.local_loc.x < 0 || guy.side == Sides.SIDE_LEFT && b.local_loc.x > 0) {
					if(guy.mode != Modes.MODE_DUNKING) {
						guy.Celebrate();
					}
					Misc.PlaySound(CROWD_$ROAR_$WAV.Get());
					if(!b.dunked && b.rimCount <= 1) {
						Misc.PlaySound(SWISH_$WAV.Get());
					}
					var guyNum = guy.side == Sides.SIDE_RIGHT ? 2 : 0;
					var aTotal = Std.parseInt(this.panel.scores[guyNum].text) + MainGame.shotPoints;
					guy.score += MainGame.shotPoints;
					if(MainGame.onlineGame) {
						var aOtherGuy = guy.GetOtherGuy();
						if(aOtherGuy != null) {
							var a = new haxe_io_BytesOutput();
							a.writeInt32(5);
							if((js_Boot.__cast(guy , HumanGuy)).isLocal) {
								a.writeInt32(guy.score);
								a.writeInt32(aOtherGuy.score);
							} else {
								a.writeInt32(aOtherGuy.score);
								a.writeInt32(guy.score);
							}
							MainGame.netCore.Send(a.getBytes());
						}
					}
					if(MainGame.IsGameWinner("" + aTotal)) {
						Misc.PlaySound(CROWD_$CLAPPING_$WAV.Get());
						this.InitPostGame(guy);
						b.mode = BallModes.HOVERING;
						b.AddMovement(1,b.local_loc.y,Main.SCREENHEIGHT / 2 + 100,600);
						b.AddMovement(4,1,0,600);
					} else {
						guy.shotStreak++;
						guy.fgMade++;
						if(MainGame.shotPoints == 3) {
							guy.threePointMade++;
							MainGame.thisMG.panel.CalcPercent();
						}
						var otherGuy = guy.GetOtherGuy();
						if(otherGuy != null && otherGuy.shotStreak >= 3) {
							otherGuy.shotStreak = 0;
						}
						if(guy.shotStreak == 3) {
							var aString = "HE'S ON FIRE!";
							if(guy.charName == "Catie Clerk") {
								aString = "SHE'S ON FIRE!";
							}
							if(guy.name == "Ca") {
								var p = MainGame.thisMG.panel.AddPopText(aString);
							}
							if(guy.mFemale) {
								Misc.PlayVoiceSound(SHESONFIRE_$WAV.Get());
							} else {
								Misc.PlayVoiceSound(ONFIRE_$WAV.Get());
							}
						}
						if(MainGame.shotPoints == 3 && guy.shotStreak != 3) {
							var a1 = this.RndInt(1,6);
							switch(a1) {
							case 1:
								MainGame.thisMG.panel.AddPopText("FROM WAY DOWN TOWN!");
								Misc.PlayVoiceSound(FROMWAYDOWNTOWN_$WAV.Get());
								break;
							case 2:
								MainGame.thisMG.panel.AddPopText("THREE POINTER!");
								Misc.PlayVoiceSound(FORTHREE_$WAV.Get());
								break;
							case 3:
								Misc.PlayVoiceSound(FROMDEEP_$WAV.Get());
								MainGame.thisMG.panel.AddPopText("FROM DEEP!");
								break;
							case 4:
								Misc.PlayVoiceSound(FROMLONGDISTANCE_$WAV.Get());
								MainGame.thisMG.panel.AddPopText("FROM LONG DISTANCE!");
								break;
							case 5:
								Misc.PlayVoiceSound(FROMTHEPARKINGLOT_$WAV.Get());
								MainGame.thisMG.panel.AddPopText("FROM THE PARKING LOT!");
								break;
							}
						}
					}
				}
			}
		}
	}
