	,chaseX: null
	,HandleScrolling: function(reset) {
		if(reset == null) {
			reset = false;
		}
		var b = this.GetChildByType(Ball);
		if(b == null) {
			return;
		}
		this.chaseX = b.local_loc.x;
		var aConst = 400 * (this.bknd.rect.width - Main.CENTERX) / (Main.SCREENWIDTH - Main.CENTERX);
		while(this.chaseX > aConst) this.chaseX--;
		while(this.chaseX < -aConst) this.chaseX++;
		var newLocX = Main.CENTERX - this.chaseX;
		this.loc.x = (this.loc.x * 15 + newLocX) / 16;
		if(reset) {
			this.loc.x = newLocX;
		}
		var middle = Main.CENTERX;
		this.bknd2.local_loc.x = this.panel.local_loc.x = (middle - this.loc.x) / 1.5;
		if(this.lights != null) {
			if(this.lights[0] != null) {
				this.lights[0].local_loc.x = this.panel.local_loc.x - 450;
			}
			if(this.lights[1] != null) {
				this.lights[1].local_loc.x = this.panel.local_loc.x - 300;
			}
			if(this.lights[2] != null) {
				this.lights[2].local_loc.x = this.panel.local_loc.x + 300;
			}
			if(this.lights[3] != null) {
				this.lights[3].local_loc.x = this.panel.local_loc.x + 450;
			}
		}
	}
