Misc.FormatMoney = function(Amount,ShowDecimal,EnglishStyle) {
	if(EnglishStyle == null) {
		EnglishStyle = true;
	}
	if(ShowDecimal == null) {
		ShowDecimal = true;
	}
	var isNegative = Amount < 0;
	Amount = Math.abs(Amount);
	var string = "";
	var comma = "";
	var amount = Math.floor(Amount);
	while(amount > 0) {
		if(string.length > 0 && comma.length <= 0) {
			comma = EnglishStyle ? "," : ".";
		}
		var zeroes = "";
		var helper = amount - Math.floor(amount / 1000) * 1000;
		amount = Math.floor(amount / 1000);
		if(amount > 0) {
			if(helper < 100) {
				zeroes += "0";
			}
			if(helper < 10) {
				zeroes += "0";
			}
		}
		string = zeroes + helper + comma + string;
	}
	if(string == "") {
		string = "0";
	}
	if(ShowDecimal) {
		amount = Math.floor(Amount * 100) - Math.floor(Amount) * 100;
		string += EnglishStyle ? "." : ",";
		if(amount < 10) {
			string += "0";
		}
		string += amount;
	}
	if(isNegative) {
		string = "-" + string;
	}
	return string;
};
Misc.GetCircleNormal = function(p1,p2) {
	var nx = p1.x - p2.x;
	var ny = p1.y - p2.y;
	var length = Math.sqrt(nx * nx + ny * ny);
	nx /= length;
	ny /= length;
	return new openfl_geom_Point(nx,ny);
};
Misc.BounceCircleOffCircle = function(vel,p1,p2) {
	var aNormal = Misc.GetCircleNormal(p1,p2);
	var vn = vel.x * aNormal.x + vel.y * aNormal.y;
	if(vn < 0) {
		var impulse = -2.0 * vn;
		return new openfl_geom_Point(vel.x + aNormal.x * impulse,vel.y + aNormal.y * impulse);
	}
	return new openfl_geom_Point(vel.x,vel.y);
};
Misc.Round = function(number,precision) {
	if(precision == null) {
		precision = 2;
	}
	number *= Math.pow(10,precision);
	return Math.round(number) / Math.pow(10,precision);
};
