	,ProcessSelection: function(selectObject) {
		var a = 0;
		if(Main.player.twoPlayerMode) {
			if(this.selectAnother) {
				Main.player.secondGuyClassName = selectObject.name;
			} else {
				Main.player.firstGuyClassName = selectObject.name;
			}
		} else {
			Main.player.firstGuyClassName = selectObject.name;
			if(Main.player.franchiseMode) {
				Main.player.franchisePlayer = selectObject.name;
			}
			do {
				a = Math.floor(Math.random() * 4);
				Main.player.secondGuyClassName = Main.player.broNames[a];
			} while(Main.player.secondGuyClassName == null || Main.player.secondGuyClassName == Main.player.firstGuyClassName);
		}
	}
	,GetSelection: function() {
		var rval = this.currentSelect;
		return rval;
	}
	,GetStatsForGuy: function(aSkeleton) {
		var aShooting = Guy.GetShooting(aSkeleton.name);
		var aHeight = Guy.GetHeight(aSkeleton.name) - 1;
		var aHops = Guy.GetHops(aSkeleton.name);
		var aSpeed = Guy.GetSpeed(aSkeleton.name);
		var aStr = "";
		if(aShooting <= 6) {
			aStr += "^1" + aShooting + "\n";
		} else if(aShooting >= 9) {
			aStr += "^2" + aShooting + "\n";
		} else {
			aStr += "^7" + aShooting + "\n";
		}
		if(aHeight <= 6) {
			aStr += "^1" + aHeight + "\n";
		} else if(aHeight >= 9) {
			aStr += "^2" + aHeight + "\n";
		} else {
			aStr += "^7" + aHeight + "\n";
		}
		if(aHops <= 6) {
			aStr += "^1" + aHops + "\n";
		} else if(aHops >= 9) {
			aStr += "^2" + aHops + "\n";
		} else {
			aStr += "^7" + aHops + "\n";
		}
		if(aSpeed <= 6) {
			aStr += "^1" + aSpeed + "\n";
		} else if(aSpeed >= 9) {
			aStr += "^2" + aSpeed + "\n";
		} else {
			aStr += "^7" + aSpeed + "\n";
		}
		return aStr;
	}
