var characterselectscreen_FranchiseScreen = function() {
	GameObject.call(this);
	if(Main.player.franchiseWeek == null) {
		Main.player.franchiseWeek = 1;
	}
	window.onwheel = function() {
		return false;
	};
	window.scrollTo(0,1);
	window.document.documentElement.style.overflow = "hidden";
	Main.HideAllAds();
	this.loc.x = Main.CENTERX;
	this.loc.y = Main.CENTERY;
	this.zOrder = 1.1;
	this.nextScreenFunction = Main.InitMainGame;
	this.AddArenaBackground();
	MainGame.AddTransition(this);
	this.AddEvent(function() {
		Misc.PlayMusic(THEME_$SELECT_$MP3.Get());
	});
	this.InitTeams();
	if(Main.player.franchiseWeek == -1) {
		this.AddLoseBox();
	} else if(Main.player.franchiseWeek == 1) {
		this.AddWelcomeBox();
	} else if(Main.player.franchiseWeek > characterselectscreen_FranchiseScreen.playoffsStartWeek) {
		this.AddTournament();
	} else {
		this.AddResults1();
	}
	var theX = new TextButton(Main.SCREENWIDTH - 20,24,"X",Main.CHAT2_FONT);
	theX.callbackFunction = Main.InitTitleScreen;
	theX.set_xScale(theX.set_yScale(Main.thisMain.isPhone() ? 1.3 : 1));
	this.children.push(theX);
};
