titlescreen_TitleScreen.AddSparkles = function(block,num,xRange,yRange,colorNum,theForce) {
	if(theForce == null) {
		theForce = false;
	}
	var _g = 0;
	var _g1 = num;
	while(_g < _g1) {
		var i = _g++;
		var o = GameObject.AddGameObject();
		var i1 = Rnd.integer(0,3);
		if(i1 == 0) {
			o.Init(INGAME_$PNG.SPARKLE01_PNG());
		} else if(i1 == 1) {
			o.Init(INGAME_$PNG.SPARKLE02_PNG());
		} else {
			o.Init(INGAME_$PNG.SPARKLE03_PNG());
		}
		o.ignoreLocalColor = true;
		o.Colorize(colorNum);
		o.holder = block;
		o.localCoords = true;
		if(o.local_loc != null) {
			o.local_loc.x = o.local_loc.y = 0;
		} else {
			o.local_loc = new openfl_geom_Point(0,0);
		}
		o.local_rot = 0;
		o.set_local_alp(1);
		o.set_local_xScale(1);
		o.set_local_yScale(1);
		o.set_local_r(1);
		o.set_local_g(1);
		o.set_local_b(1);
		var h = o.holder;
		if(h != null) {
			var hRot = h.rot;
			var hXScale = h.xScale;
			var hYScale = h.yScale;
			var hHandleX = o.local_loc.x + h.handle.x;
			var hHandleY = o.local_loc.y + h.handle.y;
			var hx = h.loc.x;
			var hy = h.loc.y;
			var a = o.xScale * o.yScale;
			o.rot = hRot + (a > 0 ? 1 : a < 0 ? -1 : 0) * o.local_rot;
			if(hRot == 0) {
				o.loc.x = hx + hXScale * hHandleX;
				o.loc.y = hy + hYScale * hHandleY;
			} else {
				var x = hRot;
				while(x < -Math.PI) x += Math.PI * 2;
				while(x > Math.PI) x -= Math.PI * 2;
				var sin = 0;
				if(x < 0) {
					sin = 1.27323954 * x + .405284735 * x * x;
				} else {
					sin = 1.27323954 * x - 0.405284735 * x * x;
				}
				var gSin = sin;
				var x1 = hRot;
				while(x1 < -Math.PI) x1 += Math.PI * 2;
				while(x1 > Math.PI) x1 -= Math.PI * 2;
				x1 += 1.57079632;
				if(x1 > 3.14159265) {
					x1 -= 6.28318531;
				}
				var cos = 1;
				if(x1 < 0) {
					cos = 1.27323954 * x1 + 0.405284735 * x1 * x1;
				} else {
					cos = 1.27323954 * x1 - 0.405284735 * x1 * x1;
				}
				var gCos = cos;
				o.loc.x = hx + hXScale * hHandleX * gCos - hYScale * hHandleY * gSin;
				o.loc.y = hy + hXScale * hHandleX * gSin + hYScale * hHandleY * gCos;
			}
		}
		o.local_loc.x = Rnd.float(-xRange,xRange);
		o.local_loc.y = Rnd.float(-yRange,yRange);
		block.children.push(o);
		var aRest = Rnd.integer(50,900);
		var m = o.AddMovement(2,0,0,aRest);
		m.loopStart = true;
		o.AddMovement(2,0,1,400);
		m = o.AddMovement(2,1,0,400);
		m.loopEnd = true;
		var m1 = o.AddMovement(3,0,0,aRest);
		m1.loopStart = true;
		o.AddMovement(3,0,1,400);
		m1 = o.AddMovement(3,1,0,400);
		m1.loopEnd = true;
		var m2 = o.AddMovement(4,0,0,aRest);
		m2.loopStart = true;
		o.AddMovement(4,0,1,400);
		m2 = o.AddMovement(4,1,0,400);
		m2.loopEnd = true;
		var aRot1 = Rnd.float(0,Math.PI);
		var aRot2 = Rnd.float(0,Math.PI);
		var m3 = o.AddMovement(5,aRot1,aRot1,aRest);
		m3.loopStart = true;
		o.AddMovement(5,aRot1,aRot2,400);
		m3 = o.AddMovement(4,aRot2,aRot2 * 2,400);
		m3.loopEnd = true;
		o.blendMode = 0;
	}
};
